package fcpxml

import (
	"bytes"
	"encoding/xml"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"
)

const maxDocumentBytes = 256 << 20

// Node is a namespace-aware XML element. Attribute order and child order are
// retained so an exported supported document can be read back consistently.
type Node struct {
	Name     xml.Name
	Attrs    []xml.Attr
	Children []*Node
	Text     string
	parent   *Node
}

// Attr returns the value of an attribute by local name. FCPXML documents
// generated by Final Cut Pro normally use no namespace, but local-name lookup
// keeps the parser tolerant of vendor namespaces.
func (n *Node) Attr(name string) string {
	if n == nil {
		return ""
	}
	for _, attribute := range n.Attrs {
		if attribute.Name.Local == name {
			return attribute.Value
		}
	}
	return ""
}

// HasAttr reports whether the element has an attribute with this local name.
func (n *Node) HasAttr(name string) bool {
	if n == nil {
		return false
	}
	for _, attribute := range n.Attrs {
		if attribute.Name.Local == name {
			return true
		}
	}
	return false
}

// Child returns the first direct child with the given local name.
func (n *Node) Child(name string) *Node {
	if n == nil {
		return nil
	}
	for _, child := range n.Children {
		if child.Name.Local == name {
			return child
		}
	}
	return nil
}

// ChildrenNamed returns all direct children with the given local name.
func (n *Node) ChildrenNamed(name string) []*Node {
	if n == nil {
		return nil
	}
	result := make([]*Node, 0, 4)
	for _, child := range n.Children {
		if child.Name.Local == name {
			result = append(result, child)
		}
	}
	return result
}

// Walk visits n and its descendants in document order.
func (n *Node) Walk(visit func(*Node) error) error {
	if n == nil {
		return nil
	}
	if err := visit(n); err != nil {
		return err
	}
	for _, child := range n.Children {
		if err := child.Walk(visit); err != nil {
			return err
		}
	}
	return nil
}

// Parent returns the containing element.
func (n *Node) Parent() *Node {
	if n == nil {
		return nil
	}
	return n.parent
}

// Path returns a compact, human-readable element path.
func (n *Node) Path() string {
	if n == nil {
		return "<nil>"
	}
	parts := make([]string, 0, 6)
	for current := n; current != nil; current = current.parent {
		part := current.Name.Local
		if id := current.Attr("id"); id != "" {
			part += "#" + id
		} else if name := current.Attr("name"); name != "" {
			part += "[" + name + "]"
		}
		parts = append(parts, part)
	}
	for left, right := 0, len(parts)-1; left < right; left, right = left+1, right-1 {
		parts[left], parts[right] = parts[right], parts[left]
	}
	return strings.Join(parts, "/")
}

// Document is a parsed FCPXML document and its ID index.
type Document struct {
	Root       *Node
	IDs        map[string]*Node
	Duplicate  []DuplicateID
	SourceName string
}

// DuplicateID describes a repeated XML id attribute.
type DuplicateID struct {
	Value  string
	First  *Node
	Second *Node
}

// Parse parses an FCPXML document from memory.
func Parse(data []byte) (*Document, error) {
	if len(data) == 0 {
		return nil, errors.New("empty FCPXML document")
	}
	if len(data) > maxDocumentBytes {
		return nil, fmt.Errorf("FCPXML document exceeds %d bytes", maxDocumentBytes)
	}
	decoder := xml.NewDecoder(bytes.NewReader(data))
	decoder.Strict = true
	root, err := decodeElement(decoder)
	if err != nil {
		return nil, err
	}
	for {
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, fmt.Errorf("parse FCPXML after root: %w", err)
		}
		switch value := token.(type) {
		case xml.CharData:
			if strings.TrimSpace(string(value)) != "" {
				return nil, errors.New("unexpected text after FCPXML root")
			}
		case xml.Comment, xml.Directive, xml.ProcInst:
		default:
			return nil, errors.New("multiple root elements in FCPXML document")
		}
	}
	if root.Name.Local != "fcpxml" {
		return nil, fmt.Errorf("root element is %q, want fcpxml", root.Name.Local)
	}

	document := &Document{Root: root, IDs: make(map[string]*Node)}
	err = root.Walk(func(node *Node) error {
		id := node.Attr("id")
		if id == "" {
			return nil
		}
		if previous, exists := document.IDs[id]; exists {
			document.Duplicate = append(document.Duplicate, DuplicateID{
				Value: id, First: previous, Second: node,
			})
			return nil
		}
		document.IDs[id] = node
		return nil
	})
	if err != nil {
		return nil, err
	}
	return document, nil
}

// Load reads and parses an FCPXML file.
func Load(path string) (*Document, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open FCPXML: %w", err)
	}
	defer file.Close()

	info, err := file.Stat()
	if err != nil {
		return nil, fmt.Errorf("stat FCPXML: %w", err)
	}
	if info.Size() > maxDocumentBytes {
		return nil, fmt.Errorf("FCPXML file %q exceeds %d bytes", path, maxDocumentBytes)
	}
	data, err := io.ReadAll(io.LimitReader(file, maxDocumentBytes+1))
	if err != nil {
		return nil, fmt.Errorf("read FCPXML: %w", err)
	}
	document, err := Parse(data)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	document.SourceName = path
	return document, nil
}

func decodeElement(decoder *xml.Decoder) (*Node, error) {
	for {
		token, err := decoder.Token()
		if err != nil {
			if err == io.EOF {
				return nil, errors.New("FCPXML document has no root element")
			}
			return nil, fmt.Errorf("decode FCPXML: %w", err)
		}
		start, ok := token.(xml.StartElement)
		if !ok {
			continue
		}
		return decodeStartElement(decoder, start)
	}
}

func decodeStartElement(decoder *xml.Decoder, start xml.StartElement) (*Node, error) {
	node := &Node{Name: start.Name, Attrs: append([]xml.Attr(nil), start.Attr...)}
	var text strings.Builder
	for {
		token, err := decoder.Token()
		if err != nil {
			return nil, fmt.Errorf("decode element %q: %w", start.Name.Local, err)
		}
		switch current := token.(type) {
		case xml.StartElement:
			child, err := decodeStartElement(decoder, current)
			if err != nil {
				return nil, err
			}
			child.parent = node
			node.Children = append(node.Children, child)
		case xml.CharData:
			text.Write(current)
		case xml.EndElement:
			node.Text = text.String()
			return node, nil
		case xml.Comment, xml.Directive, xml.ProcInst:
			// Comments and processing instructions do not affect timing.
		}
	}
}

// MarshalXML emits the node with stable indentation and exact attribute values.
func (n *Node) MarshalXML(encoder *xml.Encoder, start xml.StartElement) error {
	return encodeNode(encoder, n, start)
}

func encodeNode(encoder *xml.Encoder, node *Node, start xml.StartElement) error {
	start.Name = node.Name
	start.Attr = append([]xml.Attr(nil), node.Attrs...)
	if err := encoder.EncodeToken(start); err != nil {
		return err
	}
	if text := strings.TrimSpace(node.Text); text != "" {
		if err := encoder.EncodeToken(xml.CharData([]byte(text))); err != nil {
			return err
		}
	}
	for _, child := range node.Children {
		if err := encodeNode(encoder, child, xml.StartElement{Name: child.Name}); err != nil {
			return err
		}
	}
	return encoder.EncodeToken(start.End())
}

// Export writes the parsed document with standard XML escaping. Elements and
// timing attributes are retained, so a supported document survives a
// write/read cycle without cut-point changes.
func (d *Document) Export(writer io.Writer) error {
	if d == nil || d.Root == nil {
		return errors.New("nil FCPXML document")
	}
	if _, err := io.WriteString(writer, xml.Header); err != nil {
		return fmt.Errorf("write FCPXML header: %w", err)
	}
	encoder := xml.NewEncoder(writer)
	encoder.Indent("", "  ")
	if err := encoder.Encode(d.Root); err != nil {
		return fmt.Errorf("encode FCPXML: %w", err)
	}
	if err := encoder.Flush(); err != nil {
		return fmt.Errorf("flush FCPXML: %w", err)
	}
	return nil
}
